'use strict';

function forecastPlain(value){return value&&typeof value==='object'&&!Array.isArray(value)}
function forecastInteger(value,fallback){return typeof value==='number'&&Number.isFinite(value)&&Number.isInteger(value)&&value>=0&&value<=10000?value:fallback}
function forecastMainItems(){return planItems.filter(function(item){return !components.some(function(component){return component.id===item.id})})}
function forecastComponentItems(){return planItems.filter(function(item){return components.some(function(component){return component.id===item.id})})}
// Aggregate sample records for the same service or whole weekend, at the same booking lead time.
const forecastInputs = {
 morgen: {
  booked: 64,
  history: [
   {period: 'week',  booked: 60, guests: 76, sold: {hamburger: 26, risotto: 28, kipsate: 22}},
   {period: 'month', booked: 70, guests: 84, sold: {hamburger: 36, risotto: 30, kipsate: 18}},
   {period: 'year',  booked: 62, guests: 80, sold: {hamburger: 34, risotto: 26, kipsate: 20}}
  ]
 },
 weekend: {
  booked: 176,
  history: [
   {period: 'week',  booked: 160, guests: 200, sold: {hamburger: 68, risotto: 76, kipsate: 56}},
   {period: 'month', booked: 176, guests: 230, sold: {hamburger: 96, risotto: 84, kipsate: 50}},
   {period: 'year',  booked: 192, guests: 230, sold: {hamburger: 100, risotto: 71, kipsate: 59}}
  ]
 }
};
function refreshForecastPeriod(period, record){
 const input=forecastInputs[period];
 const attendanceRows=input.history.filter(row=>forecastInteger(row.booked,null)!==null && forecastInteger(row.guests,null)!==null);
 const booked=attendanceRows.reduce((sum,row)=>sum+row.booked,0);
 const guests=attendanceRows.reduce((sum,row)=>sum+row.guests,0);
 record.baseGuests=booked ? Math.round(input.booked*guests/booked) : input.booked;
 record.guests=record.guestOverride===null ? record.baseGuests : record.guestOverride;
 record.automatic={};
 record.expected={};
 for(const item of planItems){
  const salesRows=input.history.filter(row=>forecastInteger(row.guests,0)>0 && forecastPlain(row.sold) && forecastInteger(row.sold[item.id],null)!==null);
  if(salesRows.length){
   const covers=salesRows.reduce((sum,row)=>sum+row.guests,0);
   const sold=salesRows.reduce((sum,row)=>sum+row.sold[item.id],0);
   record.automatic[item.id]=Math.round(record.guests*sold/covers);
  }
  record.expected[item.id]=record.dishOverrides[item.id] ?? record.automatic[item.id] ?? 0;
 }
}
function initForecast(storedForecast){
 const incoming=forecastPlain(storedForecast)?storedForecast:{};
 const clean={modelVersion:1,period:incoming.period==='weekend'?'weekend':'morgen',periods:{}};
 for(const period of ['morgen','weekend']){
  const source=incoming.periods && forecastPlain(incoming.periods[period]) ? incoming.periods[period] : {};
  const record={
   guestOverride:forecastInteger(source.guestOverride,null),
   dishOverrides:{},
   buffer:[0,5,10,15,20].includes(source.buffer)?source.buffer:0
  };
  // Older snapshots recorded the resolved sample and edits together. Only promote
  // differences from their original defaults to overrides, so a saved zero is kept.
  if(incoming.modelVersion!==1 && forecastPlain(source.expected)){
   const oldGuests=period==='morgen'?80:220;
   const oldDefaults=period==='morgen'?{hamburger:32,risotto:28,kipsate:20}:{hamburger:88,risotto:77,kipsate:55};
   const savedGuests=forecastInteger(source.guests,null);
   if(savedGuests!==null && savedGuests!==oldGuests)record.guestOverride=savedGuests;
   for(const item of planItems){
    const saved=forecastInteger(source.expected[item.id],null);
    if(saved!==null && saved!==(oldDefaults[item.id]??0))record.dishOverrides[item.id]=saved;
   }
  }else if(forecastPlain(source.dishOverrides)){
   for(const item of planItems){
    const saved=forecastInteger(source.dishOverrides[item.id],null);
    if(saved!==null)record.dishOverrides[item.id]=saved;
   }
  }
  refreshForecastPeriod(period,record);
  clean.periods[period]=record;
 }
 state.forecast=clean;
 forecastSyncLegacy();
 return clean;
}
function forecastRecord(){
 return state.forecast.periods[state.forecast.period];
}
function setForecastGuests(value){
 if(value!==null && forecastInteger(value,null)===null)return;
 const record=forecastRecord();
 record.guestOverride=value;
 refreshForecastPeriod(state.forecast.period,record);
}
function setForecastQuantity(id,value){
 if(!planItems.some(item=>item.id===id))return;
 const record=forecastRecord();
 if(value===null)delete record.dishOverrides[id];
 else if(forecastInteger(value,null)!==null)record.dishOverrides[id]=value;
 else return;
 refreshForecastPeriod(state.forecast.period,record);
}
function forecastSyncLegacy(){
 const record=state.forecast.periods[state.forecast.period];
 state.mode='keukenlijst';state.covers=record.guests;state.buffer=record.buffer;
 state.manual=Object.fromEntries(planItems.map(function(item){return [item.id,record.expected[item.id]||0]}));
}
function forecastQuantity(item){const record=forecastRecord();return Math.ceil((record.expected[item.id]||0)*(1+record.buffer/100)-1e-9)}
function forecastSummary(){
 const record=forecastRecord(),main=forecastMainItems(),loose=forecastComponentItems();
 return {period:state.forecast.period,label:periodLabel(),guests:record.guests,expectedSales:main.reduce(function(sum,item){return sum+(record.expected[item.id]||0)},0),prepPortions:main.reduce(function(sum,item){return sum+forecastQuantity(item)},0),componentQty:loose.reduce(function(sum,item){return sum+forecastQuantity(item)},0),buffer:record.buffer,recipeCount:planItems.filter(function(item){return forecastQuantity(item)>0}).length};
}

.forecast-guests > label { color: var(--muted); font-size: 12px; font-weight: 650; }
.forecast-guests > small, .forecast-dish-source { color: var(--muted); font-size: 12px; }
.forecast-help { line-height: 1.55; }
.forecast-adjustment { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 12px; color: var(--green); margin-bottom: 5px; }
.forecast-restore { background: transparent; color: var(--green); text-decoration: underline; text-underline-offset: 3px; padding: 5px 0; font-weight: 650; }
.forecast-sources { background: white; border: 1px solid var(--line); border-radius: 9px; margin: -8px 0 20px; padding: 12px 18px; }
.forecast-sources summary { color: var(--green); cursor: pointer; }
.forecast-sources summary small { margin-left: 8px; font-size: 12px; color: var(--muted); }
.forecast-sources p { max-width: 75ch; margin: 12px 0 6px; }
.forecast-sources table { width: 100%; border-collapse: collapse; font-size: 13px; font-variant-numeric: tabular-nums; white-space: normal; }
.forecast-sources caption { text-align: left; padding: 10px 0; font-weight: bold; color: var(--green); }
.forecast-sources th, .forecast-sources td { padding: 7px 5px; text-align: right; border-bottom: 1px solid var(--line); white-space: normal; }
.forecast-sources th[scope=row] { width: 44%; text-align: left; font-weight: 500; }
.forecast-dish-source { display: block; margin-top: 4px; }
.forecast-dish-source .forecast-restore { margin-left: 8px; }
@media (max-width: 500px) {
  .forecast-sources { padding: 12px; }
  .forecast-sources table { table-layout: fixed; font-size: 12px; overflow-wrap: anywhere; }
  .forecast-sources thead td { width: 43%; }
  .forecast-sources th, .forecast-sources td { padding: 6px 3px; }
  .forecast-sources summary small { display: inline-block; }
}

/* Display the sources and adjustments for the selected service. */
