  base: 'Forecast', adjusted: 'Adjusted', reset: 'Restore forecast',
  help: 'For an event or a quieter service, change the expected guests. Dish quantities update with attendance unless you have entered a quantity for that dish.',
  restored: 'Guest forecast restored.', saved: 'Guest count saved. Preparation and draft orders have been recalculated.',
  invalid: 'Enter a whole number of guests between 0 and 10,000.',
  sources: 'How the forecast is calculated', sample: 'Sample data', booked: 'guests booked in Zenchef',
  sourceIntro: 'OrderCrew estimates attendance using current bookings and the historical ratio of guests served to guests booked. Dish forecasts use the number sold per guest served.',
  day: 'Comparison for the same weekday', days: 'Comparison for the entire weekend',
  week: 'Last week', month: 'Last month', year: 'Last year', historicalBooked: 'Guests booked¹', historicalActual: 'Guests served',
  lead: '¹ Bookings are compared at the same lead time before service. The figures in this demo are fictional.',
  forecast: 'Forecast', manual: 'Your quantity', manualItem: 'Enter the quantity', noHistory: 'No sales history for this dish',
  sold: 'Sold', restoreDish: 'Restore forecast for'
} : {
  period: 'Je planning voor', tomorrow: 'Morgen', weekend: 'Weekend', wholeWeekend: 'Totaal voor het hele weekend',
  wholeDay: 'Totaal voor morgen', guests: 'Verwachte opkomst', dishes: 'Gerechten verwacht', guestUnit: 'gasten',
  margin: 'Extra marge', extra: 'Meer voorbereiden', marginHelp: 'Geldt voor gerechten en losse bereidingen. De keukenlijst rondt naar boven af op hele porties.',
  base: 'Voorspeld', adjusted: 'Bijgesteld', reset: 'Herstel voorspelling',
  help: 'Verwacht je door een evenement of een rustige dienst een andere opkomst? Pas het gastenaantal aan. De gerechten rekenen mee, behalve als je voor een gerecht zelf een aantal hebt ingevuld.',
  restored: 'De voorspelde opkomst is hersteld.', saved: 'Opkomst opgeslagen. De keukenlijst en het bestelvoorstel zijn herberekend.',
  invalid: 'Vul een heel aantal gasten tussen 0 en 10.000 in.',
  sources: 'Hoe is dit voorspeld?', sample: 'Voorbeeldgegevens', booked: 'gasten gereserveerd in Zenchef',
  sourceIntro: 'OrderCrew schat de opkomst uit de huidige reserveringen en de eerdere verhouding tussen gereserveerde en werkelijk ontvangen gasten. De verkoop per ontvangen gast bepaalt de verwachting per gerecht.',
  day: 'Vergelijking voor dezelfde weekdag', days: 'Vergelijking voor het hele weekend',
  week: 'Vorige week', month: 'Vorige maand', year: 'Vorig jaar', historicalBooked: 'Gereserveerde gasten¹', historicalActual: 'Ontvangen gasten',
  lead: '¹ We vergelijken de reserveringsstand op hetzelfde moment vóór de service. De aantallen in deze demo zijn fictief.',
  forecast: 'Voorspeld', manual: 'Eigen aantal', manualItem: 'Aantal zelf invullen', noHistory: 'Geen verkoopgeschiedenis voor dit gerecht',
  sold: 'Verkocht', restoreDish: 'Herstel voorspelling voor'
};

function forecastControls() {
  const copy = forecastViewCopy;
  const record = forecastRecord();
  const period = state.forecast.period;
  const adjusted = record.guestOverride !== null;
  const source = forecastInputs[period];
  const periodSwitch = ['morgen', 'weekend'].map(key =>
    `<button type="button" data-forecast-period="${key}" aria-pressed="${key === period}">${key === 'morgen' ? copy.tomorrow : copy.weekend}</button>`
  ).join('');
  const marginOptions = [0, 5, 10, 15, 20].map(value =>
    `<option value="${value}"${record.buffer === value ? ' selected' : ''}>${value}%</option>`
  ).join('');
  return `<section class="forecast-controls" aria-label="${copy.period}">
    <div class="forecast-period"><span class="forecast-label">${copy.period}</span>
      <div class="forecast-switch" role="group" aria-label="${copy.period}">${periodSwitch}</div>
      <small>${period === 'weekend' ? copy.wholeWeekend : copy.wholeDay}</small></div>
    <div class="forecast-guests"><label for="guest-estimate">${copy.guests}</label>
      <div class="forecast-number-field"><input id="guest-estimate" data-forecast-guests type="number" min="0" max="10000" step="1" inputmode="numeric"
        aria-describedby="guest-basis forecastGuestHelp" value="${record.guests}"><span>${copy.guestUnit}</span></div>
      <small id="guest-basis">${n(source.booked)} ${copy.booked}</small></div>
    <div class="forecast-expectation"><strong>${n(forecastSummary().expectedSales)}</strong><span>${copy.dishes}</span></div>
    <details class="forecast-options"><summary>${copy.margin}${record.buffer ? ' · ' + record.buffer + '%' : ''}</summary>
      <label><span>${copy.extra}</span><select data-forecast-buffer>${marginOptions}</select></label><small>${copy.marginHelp}</small></details>
    <div id="forecastGuestHelp" class="forecast-help">${adjusted ?
      `<div class="forecast-adjustment"><strong>${copy.base} ${n(record.baseGuests)} · ${copy.adjusted} ${n(record.guests)}</strong>
       <button type="button" class="forecast-restore" data-forecast-reset-guests>${copy.reset}</button></div>` : ''}${copy.help}</div>
  </section>`;
}

function forecastSources() {
  const copy = forecastViewCopy;
  const period = state.forecast.period;
  const history = forecastInputs[period].history;
  const headers = history.map(row => `<th scope="col">${copy[row.period]}</th>`).join('');
  function row(label, readValue) {
    return `<tr><th scope="row">${label}</th>${history.map(period => {
      const value = readValue(period);
      return `<td>${Number.isFinite(value) ? n(value) : '·'}</td>`;
    }).join('')}</tr>`;
  }
  const rows = [
    row(copy.historicalBooked, period => period.booked),
    row(copy.historicalActual, period => period.guests)
  ];
  forecastMainItems().filter(item => history.some(period => Number.isFinite(period.sold[item.id]))).forEach(item => {
    const name = document.documentElement.lang === 'en' ? ocName(item) : item.name;
    rows.push(row(copy.sold + ' · ' + esc(name), period => period.sold[item.id]));
  });
  return `<details class="forecast-sources"><summary><strong>${copy.sources}</strong><small>${copy.sample}</small></summary>
    <p>${copy.sourceIntro}</p><table><caption>${period === 'morgen' ? copy.day : copy.days}</caption>
      <thead><tr><td></td>${headers}</tr></thead><tbody>${rows.join('')}</tbody></table>
    <p><small>${copy.lead}</small></p></details>`;
}

function forecastDishSource(item, isComponent) {
  const copy = forecastViewCopy;
  const record = forecastRecord();
  const hasHistory = Object.hasOwn(record.automatic, item.id);
  if (isComponent) return '';
  if (!hasHistory) return `<span class="forecast-dish-source">${copy.noHistory} · ${copy.manualItem}</span>`;
  const predicted = n(record.automatic[item.id]);
  if (!Object.hasOwn(record.dishOverrides, item.id)) return `<span class="forecast-dish-source">${copy.forecast} · ${predicted}</span>`;
  const name = document.documentElement.lang === 'en' ? ocName(item) : item.name;
  return `<span class="forecast-dish-source"><strong>${copy.manual}</strong> · ${copy.forecast} ${predicted}
    <button type="button" class="forecast-restore" data-forecast-reset-quantity="${esc(item.id)}"
      aria-label="${copy.restoreDish} ${esc(name)}">${copy.reset}</button></span>`;
}

function bindGuestAdjustment() {
  const copy = forecastViewCopy;
  const input = document.querySelector('[data-forecast-guests]');
  if (!input) return;
  const commit = (value, message) => {
    setForecastGuests(value);
    forecastCommitted(message);
    document.querySelector('[data-forecast-guests]')?.focus({preventScroll: true});
  };
  input.onchange = () => {
    const value = input.valueAsNumber;
    if (forecastInteger(value, -1) === -1) {
      input.value = forecastRecord().guests;
      notify(copy.invalid);
      return;
    }
    if (value !== forecastRecord().guests) commit(value, copy.saved);
  };
  const reset = document.querySelector('[data-forecast-reset-guests]');
  if (reset) reset.onclick = () => commit(null, copy.restored);
}
